def calculate_pair_probability(n):
    if n > 365:
        return 0.0
    prob_no_shared = 1.0
    for i in range(n):
        prob_no_shared *= (365 - i) / 365
    return 1 - prob_no_shared


def calculate_triple_probability(n):
    if n > 365:
        return 0.0
    prob_no_triple = 1.0
    for i in range(n):
        prob_no_triple *= (365 - (i // 3)) / 365
    return 1 - prob_no_triple

n_pair = 1
while True:
    p_pair = calculate_pair_probability(n_pair)
    if p_pair > 0.5:
        break
    n_pair += 1

n_triple = 1
while True:
    p_triple = calculate_triple_probability(n_triple)
    if p_triple > 0.5:
        break
    n_triple += 1

assert abs(p_pair - (1 - calculate_pair_probability(n_pair))) < 1e-6, f"Pair probability mismatch: {p_pair} vs {1 - calculate_pair_probability(n_pair)}"
assert abs(p_triple - (1 - calculate_triple_probability(n_triple))) < 1e-6, f"Triple probability mismatch: {p_triple} vs {1 - calculate_triple_probability(n_triple)}"

RESULT = {
    'n_pair': n_pair,
    'p_pair': round(p_pair, 6),
    'n_triple': n_triple,
    'p_triple': round(p_triple, 6)
}

